import{_ as o,o as t,c as d,a2 as r}from"./chunks/framework.B8TleWq7.js";const u=JSON.parse('{"title":"Console","description":"","frontmatter":{},"headers":[],"relativePath":"guides/console.md","filePath":"guides/console.md"}'),n={name:"guides/console.md"};function a(s,e,c,i,l,m){return t(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="console" tabindex="-1">Console <a class="header-anchor" href="#console" aria-label="Permalink to &quot;Console&quot;">​</a></h1><p>An in-game admin console (built on Cmdr) for testing and moderation, and per-tag log switches.</p><table tabindex="0"><thead><tr><th>File</th><th>What it is</th></tr></thead><tbody><tr><td><code>KeelServer/Vendor/Cmdr/</code></td><td>Cmdr, vendored unchanged apart from two directive lines per file</td></tr><tr><td><code>KeelServer/Console/Cmdr.luau</code></td><td>the one place that requires Cmdr</td></tr><tr><td><code>KeelServer/Console/init.luau</code></td><td>server Service (<code>Console</code>, depends on <code>Replica</code> and <code>Policy</code>): the permission rule, registering commands, mirroring <code>Account.Admin</code></td></tr><tr><td><code>KeelServer/Console/Commands/</code></td><td>Keel&#39;s commands: one Cmdr module per command, plus a <code>…Server</code> module for the part that runs on the server</td></tr><tr><td><code>KeelServer/Console/Types/</code></td><td>Cmdr argument types</td></tr><tr><td><code>Keel/Client/Console.luau</code></td><td>client half: binds <strong>F2</strong> and enables the window only while <code>Account.Admin</code> is true</td></tr><tr><td><code>Server/Defs/Admins.luau</code></td><td>this game&#39;s admin UserIds (server only)</td></tr></tbody></table><h2 id="who-may-use-it" tabindex="-1">Who may use it <a class="header-anchor" href="#who-may-use-it" aria-label="Permalink to &quot;Who may use it&quot;">​</a></h2><ul><li><strong>Studio:</strong> everyone.</li><li><strong>Any other server:</strong> only the UserIds in <code>Server/Defs/Admins</code>. A Cmdr <code>BeforeRun</code> hook refuses everyone else, whatever the client does. The client window is only a convenience.</li></ul><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><p>Open the console with <strong>F2</strong>.</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>log &lt;tag&gt; &lt;on|off|only&gt;</code></td><td>mutes or restores a tag&#39;s <code>Info</code> lines on the server and every client (<code>Warn</code> and <code>Error</code> are never muted). <code>only</code> mutes every other tag; the tag <code>*</code> means all (<code>log * off</code>, <code>log * on</code>)</td></tr><tr><td><code>policy</code></td><td>prints the Roblox policy flags your client has</td></tr><tr><td><code>testbuy &lt;product&gt; [times]</code></td><td>Studio only: a pretend developer-product purchase; with <code>times</code> above 1 the same receipt is sent again each time</td></tr><tr><td><code>testpass &lt;pass&gt; &lt;on|off|clear&gt;</code></td><td>Studio only: pretend you own (or do not own) a pass; <code>clear</code> goes back to asking Roblox</td></tr><tr><td><code>livedefs</code></td><td>lists the server-only Defs values that live configs have changed</td></tr></tbody></table><p>Cmdr&#39;s own groups are registered too (kick, ban, announce and the rest of <code>DefaultAdmin</code>, <code>DefaultDebug</code>, <code>DefaultUtil</code>, <code>Help</code>).</p><h2 id="adding-a-command" tabindex="-1">Adding a command <a class="header-anchor" href="#adding-a-command" aria-label="Permalink to &quot;Adding a command&quot;">​</a></h2><p>Add <code>Commands/name.luau</code> (returns Cmdr&#39;s definition table: <code>Name</code>, <code>Description</code>, <code>Group = &quot;Keel&quot;</code>, <code>Args</code>) and, if it must run on the server, <code>Commands/nameServer.luau</code> (returns <code>function(context, ...)</code> that returns a string). No other change is needed.</p><p><strong>Autocomplete from Defs:</strong> a module in <code>Console/Types/</code> returning <code>function(registry) CmdrType(registry, &quot;product&quot;, &quot;Products&quot;) end</code> makes an argument type that suggests the ids of a Defs kind. A command argument then says <code>Type = &quot;product&quot;</code>. The client has only the shared kinds: for a server-only kind it suggests nothing and accepts any text, and the server still rejects an id that does not exist when the command runs. See <a href="/Keel-Docs/api/cmdrtype">CmdrType</a>.</p><h2 id="log-switches" tabindex="-1">Log switches <a class="header-anchor" href="#log-switches" aria-label="Permalink to &quot;Log switches&quot;">​</a></h2><p><code>Log</code> reads a string attribute <code>LogOff</code> on <code>ReplicatedStorage</code>: tags to mute, comma separated (<code>Data,Replica</code>); <code>*</code> mutes every tag and <code>-Name</code> exempts one (<code>*,-Replica</code> keeps only <code>Replica</code>). It is read when <code>Log</code> loads and followed live; it replicates, so setting it on the server mutes the tag on every client. Set it in the Properties panel, or with the <code>log</code> command. <code>Info</code> never prints outside Studio anyway.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Cmdr moves its <code>CmdrClient</code> folder into <code>ReplicatedStorage</code> when first required (Console does that in <code>Init</code>). Do not require the vendored Cmdr from anywhere else, and do not require it from the command bar: it would run a second copy and fail.</p></div><p>See the <a href="/Keel-Docs/api/server-console">Console (server)</a> and <a href="/Keel-Docs/api/client-console">Console (client)</a> API pages.</p>',16)])])}const p=o(n,[["render",a]]);export{u as __pageData,p as default};
